INSERT INTO universites (slug, nom, description, ville, site_web, annee_creation, statut, contact_email, contact_telephone, stats_etudiants, stats_ecoles, stats_campuses, histoire, presentation, admission_info)
VALUES ('unstim', 'Université Nationale des Sciences, Technologies, Ingénierie et Mathématiques', 'L''UNSTIM, c''est LA référence béninoise pour tout ce qui touche à l''ingénierie, à la technique et à l''enseignement technique. Si tu te vois plus tard en génie civil, en électrotechnique, en informatique industrielle ou prof de technique dans un lycée, c''est très probablement ici que ça se passe.', 'Abomey / Natitingou / Lokossa', NULL, 2014, 'Publique', NULL, NULL, NULL, '8', 'Abomey, Natitingou, Lokossa', 'L''UNSTIM voit le jour en 2014, quand l''État béninois décide de regrouper sous une même bannière les grandes écoles techniques et technologiques du pays (INSTI, ENSET, ENS de Natitingou...) pour en faire un pôle d''excellence unique, dédié aux sciences, à la technologie, à l''ingénierie et aux mathématiques.', 'L''université est répartie sur plusieurs villes du Bénin et regroupe des écoles très différentes : l''ENSET forme les futurs professeurs techniques, l''INSTI et les écoles nationales supérieures (ENSGEP, ENSTP...) forment des techniciens supérieurs et futurs ingénieurs, l''ENSBBA et la FAST de Natitingou couvrent les biotechnologies, les mathématiques et la physique-chimie, tandis que l''INSPEI prépare aux concours des grandes écoles d''ingénieurs.', 'L''entrée se fait presque partout au concours (dans les écoles normales et à l''INSPEI), ou par classement du bac (INSTI, ENSBBA, ENSGEP, ENSTP, FAST). Bourses, places FPP ou payantes selon les quotas et ton classement, via apresmonbac.bj.')
