INSERT INTO universites (slug, nom, description, ville, site_web, annee_creation, statut, contact_email, contact_telephone, stats_etudiants, stats_ecoles, stats_campuses, histoire, presentation, admission_info)
VALUES ('una', 'Université Nationale d''Agriculture', 'L''UNA, c''est l''université 100% dédiée à l''agriculture, à l''élevage, à la pêche et à tout ce qui tourne autour : agroalimentaire, foresterie, agrobusiness... L''objectif est clair depuis sa création : former les cadres qui feront du Bénin un pays capable de nourrir sa population par lui-même.', 'Kétou', NULL, 2016, 'Publique', NULL, NULL, NULL, '8', NULL, 'L''UNA est née en 2016 d''une grande réforme de la carte universitaire béninoise, qui a rassemblé plusieurs écoles agricoles existantes en une université thématique unique, entièrement tournée vers la souveraineté alimentaire et le développement rural.', 'Ses écoles couvrent toute la chaîne agricole : production végétale et semences, aquaculture, horticulture, transformation et conservation des produits agricoles, génie rural, agrobusiness, sociologie rurale et vulgarisation agricole, foresterie tropicale. De vraies fermes-écoles et des laboratoires permettent une formation très pratique.', 'L''admission se fait par classement national du bac. La plupart des filières sont ouvertes aux séries scientifiques (C, D) et aux DEAT (bac technique agricole), avec des quotas de bourses et de places FPP fixés chaque année selon la filière choisie.')
