INSERT INTO universites (slug, nom, description, ville, site_web, annee_creation, statut, contact_email, contact_telephone, stats_etudiants, stats_ecoles, stats_campuses, histoire, presentation, admission_info)
VALUES ('ecoles-inter-etats', 'Écoles Inter-États', 'Derrière ce nom un peu administratif se cachent des écoles régionales de haut niveau, financées et reconnues par plusieurs pays d''Afrique de l''Ouest et du Centre à la fois. Le Bénin y réserve chaque année un quota de places à ses bacheliers, sur des filières rares et très recherchées : médecine vétérinaire, architecture, télécommunications, statistique, démographie...', NULL, NULL, NULL, 'Publique (inter-états)', NULL, NULL, NULL, '6', NULL, NULL, 'Ce groupe rassemble l''École Inter-États des Sciences et Médecine Vétérinaires (EISMV, à Dakar), l''École Africaine des Métiers de l''Architecture et de l''Urbanisme (EAMAU, à Lomé), l''École Supérieure Multinationale des Télécommunications (ESMT, à Dakar), l''Institut de Formation et de Recherche Démographique (IFORD, à Yaoundé), le Centre d''Appui aux Écoles Africaines de Statistique (CAPESA) et l''École Centrale de Casablanca. Ce sont des écoles à vocation régionale, mutualisées entre plusieurs pays membres.', 'L''accès se fait sur concours, avec un quota de places réservé chaque année aux bacheliers béninois (généralement bac C ou D). Les places obtenues sont financées comme des bourses d''État.')
