-- ---------- ECOLES ----------
INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-regional-de-sante-publique-irsp', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut Régional de Santé Publique (IRSP)', 'IRSP (Institut Régional de Santé Publique) fait partie des établissements de l''UAC. On y prépare concrètement à la filière « Santé publique polyvalente », avec les hôpitaux et centres de santé en toile de fond.', 1)
