INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('faculte-des-lettres-arts-et-sciences-humaines-adjarra-flash-adjarra', (SELECT id FROM universites WHERE slug = 'uac'), 'Faculté des Lettres, Arts et Sciences Humaines Adjarra (FLASH-Adjarra)', 'Membre de l''UAC, FLASH-Adjarra (Faculté des Lettres, Arts et Sciences Humaines Adjarra) forme sur les langues et les lettres à travers 2 filières : « Géographie et Aménagement du Territoire » ou « Socio-Anthropologie ».', 2)
ON CONFLICT (slug) DO UPDATE SET
