  programmes_count = EXCLUDED.programmes_count, updated_at = now();
INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-de-mathematiques-et-de-sciences-physiques-imsp', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut de Mathématiques et de Sciences Physiques (IMSP)', 'IMSP (Institut de Mathématiques et de Sciences Physiques) fait partie des établissements de l''UAC. On y prépare concrètement à la filière « Classes préparatoires Mathématiques, Physique-Chimie et Sciences de l''Ingénieur (MPSI) et Physique-Chimie et Science de l''Ingénieur (PCSI) », avec la recherche scientifique en toile de fond.', 1)
