INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('faculte-des-lettres-arts-langues-et-communications-fllac', (SELECT id FROM universites WHERE slug = 'uac'), 'Faculté des Lettres, Arts, Langues et Communications (FLLAC)', 'Envie de te former dans les langues et les lettres ? FLLAC (Faculté des Lettres, Arts, Langues et Communications), de l''UAC, propose 5 filières : « Allemand », « Anglais », « Espagnol », « Lettres Modernes » ou « Sciences du Langage et de la Communication ».', 5)
