INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-national-des-metiers-darts-darcheologie-et-de-la-culture-inmaac', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut National des Métiers d''Arts, d''Archéologie et de la Culture (INMAAC)', 'INMAAC (Institut National des Métiers d''Arts, d''Archéologie et de la Culture) fait partie des établissements de l''UAC. On y prépare concrètement à des filières comme « Administration Culturelle », « Arts dramatiques », « Arts Plastiques », « Musique et Musicologie » ou « Cinéma et Audiovisuel », avec la création artistique et culturelle en toile de fond.', 5)
