INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('centre-inter-facultaire-de-formation-et-de-recherche-en-environnement-pour-le-de', (SELECT id FROM universites WHERE slug = 'uac'), 'Centre Inter-Facultaire de Formation et de Recherche en Environnement pour le Développement Durable (CIFRED)', 'CIFRED (Centre Inter-Facultaire de Formation et de Recherche en Environnement pour le Développement Durable) fait partie des établissements de l''UAC. On y prépare concrètement à la filière « Environnement, Hygiène et Santé publique », avec la gestion des ressources naturelles en toile de fond.', 1)
