INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-du-cadre-de-vie-igate', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut du Cadre de Vie (IGATE)', 'IGATE (Institut du Cadre de Vie), c''est une école de l''UAC, tournée vers le génie et la technique. Elle propose 4 filières : « Gestion du cadre de vie », « Gestion des changements climatiques et des écosystèmes », « Géomatique et Environnement » ou « Planification et Gestion des espaces urbains et ruraux ».', 4)
ON CONFLICT (slug) DO UPDATE SET
