  programmes_count = EXCLUDED.programmes_count, updated_at = now();
INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-national-medico-sanitaire-inmes', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut National Médico-Sanitaire (INMeS)', 'INMeS (Institut National Médico-Sanitaire) fait partie des établissements de l''UAC. On y prépare concrètement à des filières comme « Sciences Infirmières » ou « Sciences Obstétricales », avec le monde de la santé en toile de fond.', 2)
