INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-national-de-leau-ine', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut National de l''Eau (INE)', 'Membre de l''UAC, INE (Institut National de l''Eau) forme sur la gestion de l’eau et des ressources naturelles à travers 6 filières : « Hydrogéologie et Gestion intégrée des Ressources », « Ecohydrologie et Gestion intégrée des Ressources », « Gestion des crises et risques liés à l''eau et au climat », « Génie rural et Maîtrise de l''Eau », « Hydraulique et Assainissement » ou « Eau Hygiène et Assainissement (EHA) ».', 6)
