  universite_id = EXCLUDED.universite_id, nom = EXCLUDED.nom, description = EXCLUDED.description,
  programmes_count = EXCLUDED.programmes_count, updated_at = now();
INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('ecole-nationale-deconomie-appliquee-et-de-management-eneam', (SELECT id FROM universites WHERE slug = 'uac'), 'École Nationale d''Économie Appliquée et de Management (ENEAM)', 'Membre de l''UAC, ENEAM (École Nationale d''Économie Appliquée et de Management) forme sur le monde de l’entreprise à travers 15 filières : « Administration des Réseaux Informatiques », « Analyse Informatique et Programmation », « Assurance », « Banque et Finance de Marché », « Banque et Institutions des Micro finances », « Marketing », « Marketing (2e mention) », « Gestion des Ressources Humaines », « Gestion des Transports », « Gestion de Logistique », « Statistique Economique et Sectorielle », « Statistique Démographique et Sociale », « Planification Local et Gestion des Projets », « Planification et Economie du Développement Régional » ou « Développement Local et Régional ».', 15)
ON CONFLICT (slug) DO UPDATE SET
  universite_id = EXCLUDED.universite_id, nom = EXCLUDED.nom, description = EXCLUDED.description,
  programmes_count = EXCLUDED.programmes_count, updated_at = now();
INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('ecole-du-patrimoine-africain-epa', (SELECT id FROM universites WHERE slug = 'uac'), 'École du Patrimoine Africain (EPA)', 'EPA (École du Patrimoine Africain), c''est une école de l''UAC, tournée vers la culture et la production artistique. Elle propose 2 filières : « Gestion Financière et Comptable » ou « Gestion du patrimoine culturel ».', 2)
