INSERT INTO ecoles (slug, universite_id, nom, description, programmes_count)
VALUES ('institut-de-formation-et-de-recherche-en-informatique-ifri', (SELECT id FROM universites WHERE slug = 'uac'), 'Institut de Formation et de Recherche en Informatique (IFRI)', 'IFRI (Institut de Formation et de Recherche en Informatique), c''est une école de l''UAC, tournée vers les réseaux, les logiciels et les données. Elle propose 5 filières : « Génie Logiciel », « Internet et Multimédia », « Intelligence artificielle (IA) », « Systèmes embarqués et Internet des Objets (SEIoT) » ou « Sécurité Informatique ».', 5)
