-- ---------- FILIERES ----------
INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sante-publique-polyvalente', (SELECT id FROM ecoles WHERE slug = 'institut-regional-de-sante-publique-irsp'), 'Santé publique polyvalente', 'Tu veux travailler au contact des malades ? La licence « Santé publique polyvalente », donnée par IRSP (Institut Régional de Santé Publique), te met sur les rails (au programme : SVT, PCT et Maths), avec des suites comme agent de santé communautaire ou responsable de surveillance épidémiologique.', '3 ans (Licence)', 'Baccalauréat C ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 17 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers agent de santé communautaire, responsable de surveillance épidémiologique, attaché de recherche en santé, assistant en planification, suivi et évaluation en santé ou agent d''hygiène et d''assainissement du milieu.', 'Selon ton classement : 17 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de SVT, PCT et Maths, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec le système de santé béninois, un premier pas vers un poste d''agent de santé communautaire.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Santé publique polyvalente » : SVT, PCT et Maths.', 17, 0, 'Classement', '["C","D"]'::jsonb, '["SVT","PCT","Maths"]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
  ecole_id = EXCLUDED.ecole_id, nom = EXCLUDED.nom, description = EXCLUDED.description, duree_etudes = EXCLUDED.duree_etudes,
  niveau_entree = EXCLUDED.niveau_entree, conditions_admission = EXCLUDED.conditions_admission, debouches = EXCLUDED.debouches,
  cout_annuel_info = EXCLUDED.cout_annuel_info, competences_visees = EXCLUDED.competences_visees, programme_resume = EXCLUDED.programme_resume,
  bourse = EXCLUDED.bourse, aide_fpp = EXCLUDED.aide_fpp, mode_entree = EXCLUDED.mode_entree, bac_recommande = EXCLUDED.bac_recommande,
  matieres = EXCLUDED.matieres, careers = EXCLUDED.careers, updated_at = now();
INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('geographie-et-amenagement-du-territoire', (SELECT id FROM ecoles WHERE slug = 'faculte-des-lettres-arts-et-sciences-humaines-adjarra-flash-adjarra'), 'Géographie et Aménagement du Territoire', '« Géographie et Aménagement du Territoire », c''est trois ans pour apprendre à manier les langues et les mots avec précision, à FLASH-Adjarra (Faculté des Lettres, Arts et Sciences Humaines Adjarra) (au programme : Français, Hist-Géo et Maths). Un ancrage clair dans la lecture, l’écriture et la culture générale, avec des suites comme enseignement.', '3 ans (Licence)', 'Baccalauréat A1, A2, B ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 60 places boursières et 340 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme enseignement, laboratoires et institutions de recherche ou assainissement.', 'Selon ton classement : 60 places boursières (gratuité + allocation de l''État) et 340 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Géographie et Aménagement du Territoire », tu es capable d''évoluer dans la traduction, l’enseignement et la médiation culturelle grâce à de bonnes bases en Français, Hist-Géo et Maths, un premier pas vers un poste d''enseignement, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Géographie et Aménagement du Territoire » : Français, Hist-Géo et Maths.', 60, 340, 'Classement', '["A1","A2","B","D"]'::jsonb, '["Français","Hist-Géo/Anglais(DT/STI)","Maths"]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
  ecole_id = EXCLUDED.ecole_id, nom = EXCLUDED.nom, description = EXCLUDED.description, duree_etudes = EXCLUDED.duree_etudes,
  niveau_entree = EXCLUDED.niveau_entree, conditions_admission = EXCLUDED.conditions_admission, debouches = EXCLUDED.debouches,
  cout_annuel_info = EXCLUDED.cout_annuel_info, competences_visees = EXCLUDED.competences_visees, programme_resume = EXCLUDED.programme_resume,
  bourse = EXCLUDED.bourse, aide_fpp = EXCLUDED.aide_fpp, mode_entree = EXCLUDED.mode_entree, bac_recommande = EXCLUDED.bac_recommande,
  matieres = EXCLUDED.matieres, careers = EXCLUDED.careers, updated_at = now();
INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('socio-anthropologie', (SELECT id FROM ecoles WHERE slug = 'faculte-des-lettres-arts-et-sciences-humaines-adjarra-flash-adjarra'), 'Socio-Anthropologie', '« Socio-Anthropologie » (FLASH-Adjarra (Faculté des Lettres, Arts et Sciences Humaines Adjarra)) s''adresse à celles et ceux qui veulent traduire, interpréter ou faire vivre une langue (au programme : Français, Hist-Géo et Maths). Un parcours de licence accessible dès le bac A1, A2, B, C, D, DEAT(toutes spécialités) ou DT/STI, pensé pour les langues et les lettres.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, D, DEAT(toutes spécialités) ou DT/STI', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 63 places boursières et 323 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers interprétariat, tourisme ou enseignements.', 'Selon ton classement : 63 places boursières (gratuité + allocation de l''État) et 323 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Français, Hist-Géo et Maths, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec les mots, les textes et la communication, un premier pas vers un poste d''interprétariat.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Socio-Anthropologie » : Français, Hist-Géo et Maths.', 63, 323, 'Classement', '["A1","A2","B","C","D","DEAT(toutes spécialités)","DT/STI"]'::jsonb, '["Français","Hist-Géo/Anglais(DT/STI)","Maths","pour DEAT: toutes les 3 matières écrites"]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
