INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sciences-obstetricales', (SELECT id FROM ecoles WHERE slug = 'institut-national-medico-sanitaire-inmes'), 'Sciences Obstétricales', '« Sciences Obstétricales » accessible dès le bac C ou D, dispensée par INMeS (Institut National Médico-Sanitaire), forme à intervenir dans les hôpitaux et centres de santé (au programme : PCT et SVT), avec des suites comme soins obstétricaux dans les hôpitaux et centres de santé.', '3 ans (Licence)', 'Baccalauréat C ou D', 'L''entrée se fait par un concours d''entrée. Cette année, 41 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme soins obstétricaux dans les hôpitaux et centres de santé.', 'Selon ton classement : 41 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Sciences Obstétricales », tu es capable d''évoluer dans le système de santé béninois grâce à de bonnes bases en PCT et SVT, un premier pas vers un poste de soins obstétricaux dans les hôpitaux et centres de santé, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Sciences Obstétricales » : PCT et SVT.', 41, 0, 'Concours', '["C","D"]'::jsonb, '["PCT","SVT"]'::jsonb, '[]'::jsonb)
