INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('marketing', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-deconomie-appliquee-et-de-management-eneam'), 'Marketing', 'Avec « Marketing », proposée par ENEAM (École Nationale d''Économie Appliquée et de Management), tu apprends à accompagner des entreprises dans leur gestion quotidienne (au programme : Economie, Etude de Cas et Français). Une licence de 3 ans tournée vers le monde de l’entreprise, avec des suites comme marketing et Communication Commerciale ou responsable du développement commercial.', '3 ans (Licence)', 'Baccalauréat B, C, D, G3 ou DT/CoM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 8 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme marketing et Communication Commerciale, responsable du développement commercial, chargé de clientèle, chargé d''études marketing, chef de publicité, marketing Digital and Community Management, responsable Marketing Digital/Digital Brand Manager, chargé de la stratégie mobile, chargé de communication web digital/CRM, responsable marketing relationnel/CRM, marketing business analyst, data miner/Data analyst, chef de projet Web, responsable e-Commerce ou digital planner.', 'Selon ton classement : 8 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Ce que tu sais faire en sortant : t''appuyer sur Economie, Etude de Cas, Français et Anglais pour évoluer sereinement dans la gestion et la finance, un premier pas vers un poste de marketing et Communication Commerciale, grâce à une bonne dose de terrain (stages, TD, projets).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Marketing » : Economie, Etude de Cas, Français, Anglais, Organisation et Mercatique administration des ressources.', 8, 0, 'Classement', '["B","C","D","G3","DT/CoM"]'::jsonb, '["Economie(B)/Maths(C-D)","Etude de Cas","Français","Anglais(LV pour B)","pour DT/CoM: Techniques Compta","Organisation","Mercatique administration des ressources","Français"]'::jsonb, '[]'::jsonb)
