INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('journalisme', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-des-sciences-et-techniques-de-la-communication-enstic'), 'Journalisme', 'Avec « Journalisme », proposée par ENSTIC (École Nationale des Sciences et Techniques de la Communication), tu apprends à analyser la société pour mieux agir dessus (au programme : Maths et Hist-Géo). Une licence de 3 ans tournée vers les sciences humaines et sociales, avec des suites comme journaliste (Presse écrite, Presse en ligne, Radio et Télévision) ou chargé de relations presse.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, D ou G3', 'L''entrée se fait par un concours d''entrée. Cette année, 20 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Sur le marché du travail, cette formation ouvre notamment vers journaliste (Presse écrite, Presse en ligne, Radio et Télévision), chargé de relations presse, gestionnaire d''entreprise/agence de presse, community manager (gestionnaire de communauté virtuelle), personnel manager, Réalisateur, spécialiste multimédia ou gestionnaire de production et post-production.', 'Selon ton classement : 20 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Maths et Hist-Géo, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec l’éducation et la formation, un premier pas vers un poste de journaliste (Presse écrite, Presse en ligne, Radio et Télévision).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Journalisme » : Maths et Hist-Géo.', 20, 0, 'Concours', '["A1","A2","B","C","D","G3"]'::jsonb, '["Maths","Hist-Géo"]'::jsonb, '[]'::jsonb)
