INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('administration-generale', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-dadministration-ena'), 'Administration Générale', '« Administration Générale », c''est trois ans pour apprendre à accompagner des dossiers administratifs ou juridiques, à ENA (École Nationale d''Administration) (au programme : Français ou Etude de cas, Français et Philo ou Economie). Un ancrage clair dans l’administration publique, avec des suites comme attaché des affaires étrangères.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, D, G1, G2 ou G3', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 70 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme attaché des affaires étrangères, attaché des services administratifs ou inspecteur du Travail et de la Sécurité Sociale.', 'Selon ton classement : 70 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Administration Générale », tu es capable d''évoluer dans la justice, les institutions et le service public grâce à de bonnes bases en Français ou Etude de cas, Français et Philo ou Economie, un premier pas vers un poste d''attaché des affaires étrangères, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Administration Générale » : Français ou Etude de cas, Français et Philo ou Economie.', 70, 0, 'Classement', '["A1","A2","B","C","D","G1","G2","G3"]'::jsonb, '["Français(A-B-C-D) ou Etude de cas(G1-G2-G3)","Français","Philo(A-B-C-D) ou Economie(G1-G2-G3)"]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
  ecole_id = EXCLUDED.ecole_id, nom = EXCLUDED.nom, description = EXCLUDED.description, duree_etudes = EXCLUDED.duree_etudes,
  niveau_entree = EXCLUDED.niveau_entree, conditions_admission = EXCLUDED.conditions_admission, debouches = EXCLUDED.debouches,
