INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('administration-des-finances', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-dadministration-ena'), 'Administration des Finances', 'ENA (École Nationale d''Administration) propose, avec « Administration des Finances », une licence tournée vers les textes juridiques et les procédures (au programme : Maths ou Etude de cas, Français et Hist-Géo ou Economie). De quoi faire appliquer la loi et les procédures dès la sortie, avec des suites comme attaché des services financiers dans les Impôts.', '3 ans (Licence)', 'Baccalauréat C, D, G2 ou G3', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 40 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme attaché des services financiers dans les Impôts, attaché des services financiers dans les Collectivités locales ou personne responsable de la planification des Marchés publics.', 'Selon ton classement : 40 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Maths ou Etude de cas, Français et Hist-Géo ou Economie, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec le droit et l’administration, un premier pas vers un poste d''attaché des services financiers dans les Impôts.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Administration des Finances » : Maths ou Etude de cas, Français et Hist-Géo ou Economie.', 0, 40, 'Classement', '["C","D","G2","G3"]'::jsonb, '["Maths(C-D) ou Etude de cas(G2-G3)","Français","Hist-Géo(G1-G2-G3) ou Economie(C-D)"]'::jsonb, '[]'::jsonb)
