INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sciences-et-techniques-de-linformation-documentaire', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-dadministration-ena'), 'Sciences et Techniques de l''Information documentaire', '« Sciences et Techniques de l''Information documentaire » (ENA (École Nationale d''Administration)) s''adresse à celles et ceux qui veulent manier le droit et les textes au quotidien (au programme : Anglais et Hist-Géo ou Economie). Un parcours de licence accessible dès le bac A1, A2, B, G, C ou D, pensé pour la justice, les institutions et le service public.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, G, C ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 38 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers technicien supérieur en archivistique ou technicien supérieur -Documentaliste.', 'Selon ton classement : 38 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Sciences et Techniques de l''Information documentaire », tu es capable d''évoluer dans la justice, les institutions et le service public grâce à de bonnes bases en Anglais et Hist-Géo ou Economie, un premier pas vers un poste de technicien supérieur en archivistique, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Sciences et Techniques de l''Information documentaire » : Anglais et Hist-Géo ou Economie.', 38, 0, 'Classement', '["A1","A2","B","G","C","D"]'::jsonb, '["Anglais(UV1 pour A, B)","Hist-Géo(A-C-D) ou Economie(pour G)"]'::jsonb, '[]'::jsonb)
