INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('genie-logiciel', (SELECT id FROM ecoles WHERE slug = 'institut-de-formation-et-de-recherche-en-informatique-ifri'), 'Génie Logiciel', 'IFRI (Institut de Formation et de Recherche en Informatique) et sa licence « Génie Logiciel » t''emmènent vers les réseaux, les logiciels et les données (au programme : Maths, Anglais ou Etude de Fabrication et Français). Tu y apprends à faire tourner les systèmes qui font tourner les entreprises, avec des suites comme analystes et concepteurs ou architectes logiciels.', '3 ans (Licence)', 'Baccalauréat C, D, E, DT/MI ou DT/WM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 17 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers analystes et concepteurs, architectes logiciels, administrateurs de bases de données, développeurs d''applications métiers ou auto-entreprenariat.', 'Selon ton classement : 17 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Génie Logiciel », tu es capable d''évoluer dans les réseaux, les logiciels et les données grâce à de bonnes bases en Maths, Anglais ou Etude de Fabrication, Français et Maths appliquées, un premier pas vers un poste d''analystes et concepteurs, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Génie Logiciel » : Maths, Anglais ou Etude de Fabrication, Français, Maths appliquées, Sites et Applications Web.', 17, 0, 'Classement', '["C","D","E","DT/MI","DT/WM"]'::jsonb, '["Maths","Anglais ou Etude de Fabrication(E)","Français","pour DT/MI: Technologie des systèmes informatiques","Maths appliquées","Sites","Applications Web(pour DT/WM)"]'::jsonb, '[]'::jsonb)
