INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('internet-et-multimedia', (SELECT id FROM ecoles WHERE slug = 'institut-de-formation-et-de-recherche-en-informatique-ifri'), 'Internet et Multimédia', '« Internet et Multimédia » (IFRI (Institut de Formation et de Recherche en Informatique)) s''adresse à celles et ceux qui veulent construire des applications et des services numériques (au programme : Maths, Anglais ou Etude de Fabrication et Français). Un parcours de licence accessible dès le bac C, D, E, DT/MI ou DT/PM, pensé pour l’informatique appliquée.', '3 ans (Licence)', 'Baccalauréat C, D, E, DT/MI ou DT/PM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 14 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers concepteurs d''applications mobiles, designers, monteurs vidéo et multimédia ou techniciens de web TV et web Radio.', 'Selon ton classement : 14 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Internet et Multimédia », tu es capable d''évoluer dans la tech et le digital grâce à de bonnes bases en Maths, Anglais ou Etude de Fabrication, Français et Maths appliquées, un premier pas vers un poste de concepteurs d''applications mobiles, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Internet et Multimédia » : Maths, Anglais ou Etude de Fabrication, Français, Maths appliquées, Sites et Applications Web.', 14, 0, 'Classement', '["C","D","E","DT/MI","DT/PM"]'::jsonb, '["Maths","Anglais ou Etude de Fabrication(E)","Français","pour DT/MI: Technologie des systèmes informatiques","Maths appliquées","Sites","Applications Web(pour DT/WM)"]'::jsonb, '[]'::jsonb)
