INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('intelligence-artificielle-ia', (SELECT id FROM ecoles WHERE slug = 'institut-de-formation-et-de-recherche-en-informatique-ifri'), 'Intelligence artificielle (IA)', '« Intelligence artificielle (IA) », c''est trois ans pour apprendre à coder, développer et déployer des outils informatiques, à IFRI (Institut de Formation et de Recherche en Informatique) (au programme : Maths, Anglais ou Etude de Fabrication et Français). Un ancrage clair dans le monde du numérique, avec des suites comme développeurs des solutions intelligentes.', '3 ans (Licence)', 'Baccalauréat C, D ou E', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 19 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Sur le marché du travail, cette formation ouvre notamment vers développeurs des solutions intelligentes, analystes des données de décisionnelles, architecte de données massives ou auto-entreprenariat.', 'Selon ton classement : 19 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Ce que tu sais faire en sortant : t''appuyer sur Maths, Anglais ou Etude de Fabrication et Français pour évoluer sereinement dans les systèmes d’information, un premier pas vers un poste de développeurs des solutions intelligentes, grâce à une bonne dose de terrain (stages, TD, projets).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Intelligence artificielle (IA) » : Maths, Anglais ou Etude de Fabrication et Français.', 19, 0, 'Classement', '["C","D","E"]'::jsonb, '["Maths","Anglais ou Etude de Fabrication(E)","Français"]'::jsonb, '[]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET
