INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('assistance-sociale', (SELECT id FROM ecoles WHERE slug = 'faculte-des-sciences-de-la-sante-fss'), 'Assistance sociale', 'FSS (Faculté des Sciences de la Santé) propose, avec « Assistance sociale », une licence tournée vers les hôpitaux et centres de santé (au programme : Philo, Hist-Géo et SVT). De quoi agir concrètement pour la santé des gens dès la sortie, avec des suites comme technicien supérieur de l''action sociale.', '3 ans (Licence)', 'Baccalauréat A1, A2, B ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 10 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme technicien supérieur de l''action sociale.', 'Selon ton classement : 10 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Philo, Hist-Géo et SVT, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec le système de santé béninois, un premier pas vers un poste de technicien supérieur de l''action sociale.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Assistance sociale » : Philo, Hist-Géo et SVT.', 10, 0, 'Classement', '["A1","A2","B","D"]'::jsonb, '["Philo","Hist-Géo","SVT"]'::jsonb, '[]'::jsonb)
