INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('genie-civil', (SELECT id FROM ecoles WHERE slug = 'ecole-polytechnique-dabomey-calavi-epac'), 'Génie Civil', 'Avec « Génie Civil », proposée par EPAC (École Polytechnique d''Abomey-Calavi), tu apprends à concevoir, construire et faire tenir debout (au programme : Maths, PCT et Anglais ou Français). Une licence de 3 ans tournée vers les infrastructures et les équipements, avec des suites comme chefs chantiers ou techniciens d''étude en entreprise.', '3 ans (Licence)', 'Baccalauréat C, D, E, F4 ou DT/BTP', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 25 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers chefs chantiers, techniciens d''étude en entreprise, conducteurs des travaux ou laboratoires.', 'Selon ton classement : 25 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Génie Civil », tu es capable d''évoluer dans le génie et la technique grâce à de bonnes bases en Maths, PCT et Anglais ou Français, un premier pas vers un poste de chefs chantiers, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Génie Civil » : Maths, PCT et Anglais ou Français.', 25, 0, 'Classement', '["C","D","E","F4","DT/BTP"]'::jsonb, '["Maths","PCT","Anglais ou Français(E, F)"]'::jsonb, '[]'::jsonb)
