INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('commerce-international', (SELECT id FROM ecoles WHERE slug = 'haute-ecole-regionale-de-commerce-international-herci'), 'Commerce International', 'Avec « Commerce International », proposée par HERCI (Haute École Régionale de Commerce International), tu apprends à piloter des budgets, des projets ou des équipes (au programme : Maths, Economie et Anglais). Une licence de 3 ans tournée vers la gestion et l’économie, avec des suites comme chef de zone import-export ou responsable de force de vente international.', '3 ans (Licence)', 'Baccalauréat B, C, D, G2 ou G3', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 7 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers chef de zone import-export, responsable de force de vente international ou chargé international.', 'Selon ton classement : 7 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Commerce International », tu es capable d''évoluer dans la gestion et la finance grâce à de bonnes bases en Maths, Economie et Anglais, un premier pas vers un poste de chef de zone import-export, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Commerce International » : Maths, Economie et Anglais.', 7, 0, 'Classement', '["B","C","D","G2","G3"]'::jsonb, '["Maths","Economie(B-C-D)/Etude de Cas(G2, G3)","Anglais"]'::jsonb, '[]'::jsonb)
