INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('developpement-communautaire', (SELECT id FROM ecoles WHERE slug = 'institut-national-de-la-jeunesse-de-leducation-physique-et-sportive-injeps'), 'Développement communautaire', '« Développement communautaire », c''est trois ans pour apprendre à accompagner des sportifs ou des groupes vers la performance, à INJEPS (Institut National de la Jeunesse de l''Éducation Physique et Sportive) (au programme : Français, Anglais et Philo). Un ancrage clair dans le sport et l’activité physique, avec des suites comme technicien Supérieur d''Action Socio-Educative.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 8 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers technicien Supérieur d''Action Socio-Educative, administrateur d''Action Socio-Educative, administrateur de programmes et projets de développement local, chef de projets ou spécialiste en planification et développement local.', 'Selon ton classement : 8 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Développement communautaire », tu es capable d''évoluer dans le sport et l’activité physique grâce à de bonnes bases en Français, Anglais et Philo, un premier pas vers un poste de technicien Supérieur d''Action Socio-Educative, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Développement communautaire » : Français, Anglais et Philo.', 8, 0, 'Classement', '["A1","A2","B","C","D"]'::jsonb, '["Français","Anglais(UV1)","Philo"]'::jsonb, '[]'::jsonb)
