INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('droit', (SELECT id FROM ecoles WHERE slug = 'faculte-de-droit-et-de-science-politique-fadesp'), 'Droit', 'FADESP (Faculté de Droit et de Science Politique) et sa licence « Droit » t''emmènent vers la justice, les institutions et le service public (au programme : Français, Anglais et Hist-Géo). Tu y apprends à manier le droit et les textes au quotidien, avec des suites comme attaché des services administratifs ou attaché des affaires étrangères.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, D ou G2', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 104 places boursières et 999 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers attaché des services administratifs, attaché des affaires étrangères, auxiliaires de justice (avocat, huissier, notaire etc) ou magistrature.', 'Selon ton classement : 104 places boursières (gratuité + allocation de l''État) et 999 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Ce que tu sais faire en sortant : t''appuyer sur Français, Anglais et Hist-Géo pour évoluer sereinement dans le droit et l’administration, un premier pas vers un poste d''attaché des services administratifs, grâce à une bonne dose de terrain (stages, TD, projets).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Droit » : Français, Anglais et Hist-Géo.', 104, 999, 'Classement', '["A1","A2","B","C","D","G2"]'::jsonb, '["Français","Anglais(UV1)","Hist-Géo/Etude de cas(G2)"]'::jsonb, '[]'::jsonb)
