INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sciences-politiques', (SELECT id FROM ecoles WHERE slug = 'faculte-de-droit-et-de-science-politique-fadesp'), 'Sciences Politiques', '« Sciences Politiques », c''est trois ans pour apprendre à manier le droit et les textes au quotidien, à FADESP (Faculté de Droit et de Science Politique) (au programme : Français, Anglais et Hist-Géo). Un ancrage clair dans la justice, les institutions et le service public, avec des suites comme diplomate.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, D ou G2', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 38 places boursières et 183 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers diplomate, spécialiste des relations internationales, spécialiste des politiques publiques, sociologue des comportements politiques, evaluateur des politiques publiques ou gestionnaire des projets.', 'Selon ton classement : 38 places boursières (gratuité + allocation de l''État) et 183 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Sciences Politiques », tu es capable d''évoluer dans le droit et les institutions grâce à de bonnes bases en Français, Anglais et Hist-Géo, un premier pas vers un poste de diplomate, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Sciences Politiques » : Français, Anglais et Hist-Géo.', 38, 183, 'Classement', '["A1","A2","B","C","D","G2"]'::jsonb, '["Français","Anglais(UV1)","Hist-Géo/Etude de cas(G2)"]'::jsonb, '[]'::jsonb)
