INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sciences-economiques-et-de-gestion-tronc-commun', (SELECT id FROM ecoles WHERE slug = 'faculte-des-sciences-economiques-et-de-gestion-faseg'), 'Sciences Economiques et de Gestion (Tronc commun)', '« Sciences Economiques et de Gestion (Tronc commun) », c''est trois ans pour apprendre à accompagner des entreprises dans leur gestion quotidienne, à FASEG (Faculté des Sciences Economiques et de Gestion) (au programme : Maths, Etude de cas et PCT). Un ancrage clair dans le monde de l’entreprise, avec des suites comme services décconcentrés de l''Etat, Collectivités locales, associations et ONG.', '3 ans (Licence)', 'Baccalauréat B, C, D, G2, G3 ou DT/CoM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 207 places boursières et 1407 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme services décconcentrés de l''Etat, Collectivités locales, associations et ONG, analystes, statisticiens, Comptable, planificateur et Gestion des Ressources financières, statistique agricole, analyse des projets agricoles, gestion des structures de collectivités, chargé des études et de la prospective économique des collectivités, economiste de marché, conseiller en Microfinance, entrepreneur, gestionnaire des PME, comptable dans les structures financières, assistant Auditeur, agent de banque ou agent d''assurance.', 'Selon ton classement : 207 places boursières (gratuité + allocation de l''État) et 1407 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Sciences Economiques et de Gestion (Tronc commun) », tu es capable d''évoluer dans le monde de l’entreprise grâce à de bonnes bases en Maths, Etude de cas, PCT et Français, un premier pas vers un poste de services décconcentrés de l''Etat, Collectivités locales, associations et ONG, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Sciences Economiques et de Gestion (Tronc commun) » : Maths, Etude de cas, PCT, Français, Organisation et Mercatique.', 207, 1407, 'Classement', '["B","C","D","G2","G3","DT/CoM"]'::jsonb, '["Maths(C-D)/Maths(B)","Etude de cas(G)/Economie","PCT","Français","pour DT/Com: Tech Compta","Organisation","Mercatique","administration rationnelle des ressources","Français"]'::jsonb, '[]'::jsonb)
