INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('econometrie-et-statistiques-appliquees', (SELECT id FROM ecoles WHERE slug = 'faculte-des-sciences-economiques-et-de-gestion-faseg'), 'Econométrie et Statistiques Appliquées', '« Econométrie et Statistiques Appliquées » (FASEG (Faculté des Sciences Economiques et de Gestion)) s''adresse à celles et ceux qui veulent gérer, chiffrer et faire tourner une activité (au programme : Maths, PCT et Français). Un parcours de licence accessible dès le bac C ou D, pensé pour la gestion et la finance.', '3 ans (Licence)', 'Baccalauréat C ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 18 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers statisticien, économètre, Analyste économiste ou conseiller en stratégies et prise de décisions.', 'Selon ton classement : 18 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Maths, PCT et Français, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec la gestion et la finance, un premier pas vers un poste de statisticien, économètre, Analyste économiste.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Econométrie et Statistiques Appliquées » : Maths, PCT et Français.', 18, 0, 'Classement', '["C","D"]'::jsonb, '["Maths","PCT","Français"]'::jsonb, '[]'::jsonb)
