INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('langue-arabe', (SELECT id FROM ecoles WHERE slug = 'institut-de-langue-arabe-et-culture-islamique-ilaci'), 'Langue Arabe', 'Se former à la traduction, l’enseignement et la médiation culturelle, c''est ce que propose « Langue Arabe » à ILACI (Institut de Langue Arabe et Culture Islamique). Objectif : transmettre une langue et une culture, avec des suites comme enseignement, Traducteur, Interprétation Journalisme et communication.', '3 ans (Licence)', 'Baccalauréat toutes séries confondues', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Les quotas de bourses et de places FPP sont fixés chaque année par le Ministère selon la filière.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme enseignement, Traducteur, Interprétation Journalisme et communication, recherche et analyse, culture, Tourisme/Agence de voyage ou ecriture/Rédacteur en publicité.', 'Pas de quota de bourse communiqué pour cette filière dans le guide officiel : renseigne-toi sur apresmonbac.bj au moment de faire tes choix pour connaître les places disponibles de l''année.', 'À la sortie de « Langue Arabe », tu maîtrises les bases théoriques et pratiques qu''il faut pour les langues et les lettres, un premier pas vers un poste d''enseignement, Traducteur, Interprétation Journalisme et communication, construites au fil des stages et travaux pratiques.', 'Le contenu précis du programme (matières, volumes horaires par semestre) est à demander directement à l''établissement.', 0, 0, 'Classement', '["toutes séries confondues"]'::jsonb, '[]'::jsonb, '[]'::jsonb)
