INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sciences-et-techniques-de-production-vegetale-2', (SELECT id FROM ecoles WHERE slug = 'faculte-dagronomie-fa'), 'Sciences et Techniques de Production Végétale', 'Avec « Sciences et Techniques de Production Végétale », proposée par FA (Faculté d''Agronomie), tu apprends à donner un métier à la terre béninoise (au programme : Maths, PCT et SVT). Une licence de 3 ans tournée vers l’agriculture et le monde rural, avec des suites comme entrepreneur Agricole, Conseiller Agricole, Technicien/Encadreur en production durable des terres, Enseignant des lycées agricoles.', '3 ans (Licence)', 'Baccalauréat C, D ou DEAT(toutes options)', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 22 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers entrepreneur Agricole, Conseiller Agricole, Technicien/Encadreur en production durable des terres, Enseignant des lycées agricoles.', 'Selon ton classement : 22 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Sciences et Techniques de Production Végétale », tu es capable d''évoluer dans l’agriculture et le monde rural grâce à de bonnes bases en Maths, PCT et SVT, un premier pas vers un poste d''entrepreneur Agricole, Conseiller Agricole, Technicien/Encadreur en production durable des terres, Enseignant des lycées agricoles, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Sciences et Techniques de Production Végétale » : Maths, PCT et SVT.', 22, 0, 'Classement', '["C","D","DEAT(toutes options)"]'::jsonb, '["Maths","PCT","SVT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
