INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('nutrition-et-sciences-agro-alimentaires', (SELECT id FROM ecoles WHERE slug = 'faculte-dagronomie-fa'), 'Nutrition et Sciences Agro-alimentaires', 'FA (Faculté d''Agronomie) et sa licence « Nutrition et Sciences Agro-alimentaires » t''emmènent vers le soin et la prévention (au programme : Maths, PCT et SVT). Tu y apprends à intervenir dans les hôpitaux et centres de santé, avec des suites comme entrepreneur Agro-alimentaire, Chef production IAA, Technicien en nutrition et sciences agroalimentaires, Enseignant des lycées agricoles.', '3 ans (Licence)', 'Baccalauréat C, D ou DEAT(toutes options)', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 20 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme entrepreneur Agro-alimentaire, Chef production IAA, Technicien en nutrition et sciences agroalimentaires, Enseignant des lycées agricoles.', 'Selon ton classement : 20 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Maths, PCT et SVT, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec le système de santé béninois, un premier pas vers un poste d''entrepreneur Agro-alimentaire, Chef production IAA, Technicien en nutrition et sciences agroalimentaires, Enseignant des lycées agricoles.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Nutrition et Sciences Agro-alimentaires » : Maths, PCT et SVT.', 20, 0, 'Classement', '["C","D","DEAT(toutes options)"]'::jsonb, '["Maths","PCT","SVT"]'::jsonb, '[]'::jsonb)
