INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('gestion-des-banques', (SELECT id FROM ecoles WHERE slug = 'institut-universitaire-de-technologie-iut'), 'Gestion des Banques', 'Se former à la gestion et l’économie, c''est ce que propose « Gestion des Banques » à IUT (Institut Universitaire de Technologie) (au programme : Maths, Français et Anglais). Objectif : piloter des budgets, des projets ou des équipes, avec des suites comme organismes financiers ou de gestion (établissement de crédits, banques centrales, entreprises commerciales de banque).', '3 ans (Licence)', 'Baccalauréat C, D ou G2', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 15 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers organismes financiers ou de gestion (établissement de crédits, banques centrales, entreprises commerciales de banque).', 'Selon ton classement : 15 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Maths, Français et Anglais, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec la finance, le commerce et la gestion de projets, un premier pas vers un poste d''organismes financiers ou de gestion (établissement de crédits, banques centrales, entreprises commerciales de banque).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Gestion des Banques » : Maths, Français et Anglais.', 15, 0, 'Classement', '["C","D","G2"]'::jsonb, '["Maths(C-D)/Etude de Cas(G)","Français","Anglais(UV1)"]'::jsonb, '[]'::jsonb)
