INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('statistiques-appliquees', (SELECT id FROM ecoles WHERE slug = 'ecole-nationale-de-statistique-de-planification-et-de-demographie-enspd'), 'Statistiques Appliquées', '« Statistiques Appliquées » accessible dès le bac C ou D, dispensée par ENSPD (École Nationale de Statistique, de Planification et de Démographie), forme à piloter des budgets, des projets ou des équipes (au programme : Culture générale et Maths), avec des suites comme planificateur dans les ministères sectoriels ou administrations nationales et cabinets.', '3 ans (Licence)', 'Baccalauréat C ou D', 'L''entrée se fait par un concours d''entrée. Cette année, 22 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme planificateur dans les ministères sectoriels, administrations nationales et cabinets ou centres ou laboratoires de recherche et cabinets d''études.', 'Selon ton classement : 22 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Statistiques Appliquées », tu es capable d''évoluer dans les entreprises, les banques et les administrations grâce à de bonnes bases en Culture générale et Maths, un premier pas vers un poste de planificateur dans les ministères sectoriels, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Statistiques Appliquées » : Culture générale et Maths.', 22, 0, 'Concours', '["C","D"]'::jsonb, '["Culture générale","Maths"]'::jsonb, '[]'::jsonb)
