INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('finance-et-comptabilite-fc', (SELECT id FROM ecoles WHERE slug = 'faculte-de-sciences-economiques-et-de-gestion-faseg'), 'Finance et Comptabilité (FC)', 'Tu veux faire le lien entre les chiffres et les décisions ? La licence « Finance et Comptabilité (FC) », donnée par FASEG (Faculté de Sciences Economiques et de Gestion), te met sur les rails, avec des suites comme auto emploi ou cabinets Conseils Financiers.', '3 ans (Licence)', 'Baccalauréat toutes séries confondues', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 76 places boursières et 243 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers auto emploi, cabinets Conseils Financiers, cabinets Conseils en Comptabilité, structures Chargées des Questions Liées aux Finances (Ministères, Administrations), projets de Développement ou entreprises de tous Genres.', 'Selon ton classement : 76 places boursières (gratuité + allocation de l''État) et 243 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Finance et Comptabilité (FC) », tu maîtrises les bases théoriques et pratiques qu''il faut pour la finance, le commerce et la gestion de projets, un premier pas vers un poste d''auto emploi, construites au fil des stages et travaux pratiques.', 'Le contenu précis du programme (matières, volumes horaires par semestre) est à demander directement à l''établissement.', 76, 243, 'Classement', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb)
