INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('fabrication-mecanique', (SELECT id FROM ecoles WHERE slug = 'ecole-normale-superieure-de-lenseignement-technique-enset'), 'Fabrication Mécanique', '« Fabrication Mécanique », c''est trois ans pour apprendre à faire tourner les machines et les infrastructures, à ENSET (École Normale Supérieure de l''Enseignement Technique) (au programme : Culture générale et PCT). Un ancrage clair dans les chantiers, les ateliers et les usines, avec des suites comme professeur adjoint des Lycées et Collèges.', '3 ans (Licence)', 'Baccalauréat C, D, E, F1 ou DT/FM', 'L''entrée se fait par un concours d''entrée. Cette année, 22 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers professeur adjoint des Lycées et Collèges.', 'Selon ton classement : 22 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Fabrication Mécanique », tu es capable d''évoluer dans le BTP et l’industrie grâce à de bonnes bases en Culture générale et PCT, un premier pas vers un poste de professeur adjoint des Lycées et Collèges, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Fabrication Mécanique » : Culture générale et PCT.', 22, 0, 'Concours', '["C","D","E","F1","DT/FM"]'::jsonb, '["Culture générale","PCT(C,D)/RDM(DT/FM,E,F1,DT/HR)"]'::jsonb, '[]'::jsonb)
