INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('economie-familiale-et-sociale', (SELECT id FROM ecoles WHERE slug = 'ecole-normale-superieure-de-lenseignement-technique-enset'), 'Economie Familiale et Sociale', 'Avec « Economie Familiale et Sociale », proposée par ENSET (École Normale Supérieure de l''Enseignement Technique), tu apprends à analyser des données économiques et financières (au programme : Culture générale, PCT et Anglais). Une licence de 3 ans tournée vers la finance, le commerce et la gestion de projets, avec des suites comme professeur adjoint des Lycées et Collèges.', '3 ans (Licence)', 'Baccalauréat A1, A2, B, C, D ou DT/EFS', 'L''entrée se fait par un concours d''entrée. Cette année, 5 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers professeur adjoint des Lycées et Collèges.', 'Selon ton classement : 5 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Ce que tu sais faire en sortant : t''appuyer sur Culture générale, PCT et Anglais pour évoluer sereinement dans le monde de l’entreprise, un premier pas vers un poste de professeur adjoint des Lycées et Collèges, grâce à une bonne dose de terrain (stages, TD, projets).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Economie Familiale et Sociale » : Culture générale, PCT et Anglais.', 5, 0, 'Concours', '["A1","A2","B","C","D","DT/EFS"]'::jsonb, '["Culture générale","PCT(C,D)/Educ santé(DT/EFS/HR)","Anglais(A1,A2)/Economie(B)"]'::jsonb, '[]'::jsonb)
