INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('genie-mecanique-et-productique', (SELECT id FROM ecoles WHERE slug = 'institut-national-superieur-de-technologie-industrielle-insti'), 'Génie Mécanique et productique', '« Génie Mécanique et productique », c''est trois ans pour apprendre à intervenir sur le terrain, du chantier à l’atelier, à INSTI (Institut National Supérieur de Technologie Industrielle) (au programme : Maths, SPCT et Anglais). Un ancrage clair dans le génie et la technique, avec des suites comme maintenance industrielle.', '3 ans (Licence)', 'Baccalauréat C, D, E, F1, DT/MA ou DT/FM', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 38 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Concrètement, ça peut t''amener vers maintenance industrielle, fabrication mécanique, parcs machines, méthodes et contrôle de la qualité, maintenance des engins agricoles ou mécanisation agricole.', 'Selon ton classement : 38 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Ce que tu sais faire en sortant : t''appuyer sur Maths, SPCT et Anglais pour évoluer sereinement dans les infrastructures et les équipements, un premier pas vers un poste de maintenance industrielle, grâce à une bonne dose de terrain (stages, TD, projets).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Génie Mécanique et productique » : Maths, SPCT et Anglais.', 38, 0, 'Classement', '["C","D","E","F1","DT/MA","DT/FM"]'::jsonb, '["Maths","SPCT","Anglais(C,D)/Construction Mécanique(E,F1,DT/FM)/Mécanique(DT/MA)"]'::jsonb, '[]'::jsonb)
