INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sciences-et-techniques-de-lingenieur', (SELECT id FROM ecoles WHERE slug = 'institut-national-superieur-des-classes-preparatoires-aux-etudes-dingenieurs-ins'), 'Sciences et Techniques de l''Ingénieur', '« Sciences et Techniques de l''Ingénieur », proposée par INSPEI (Institut National Supérieur des Classes Préparatoires aux Études d''Ingénieurs), ce sont deux années de classes préparatoires intégrées en t''appuyant surtout sur PCT et Maths. Objectif : intégrer ensuite un cycle ingénieur (3 années supplémentaires), avec des suites comme ingénieur de conception (après 3 ans d''études dans les écoles d''ingénieurs au sein de l''UNSTIM).', '2 ans de classes préparatoires, puis 3 ans en cycle ingénieur', 'Baccalauréat C, D ou E', 'L''entrée se fait par un concours d''entrée. Cette année, 83 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers ingénieur de conception (après 3 ans d''études dans les écoles d''ingénieurs au sein de l''UNSTIM).', 'Selon ton classement : 83 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de PCT et Maths, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec le BTP et l’industrie, un premier pas vers un poste d''ingénieur de conception (après 3 ans d''études dans les écoles d''ingénieurs au sein de l''UNSTIM).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Sciences et Techniques de l''Ingénieur » : PCT et Maths.', 83, 0, 'Concours', '["C","D","E"]'::jsonb, '["PCT","Maths"]'::jsonb, '[]'::jsonb)
