INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('mathematiques-informatiques', (SELECT id FROM ecoles WHERE slug = 'faculte-des-sciences-et-techniques-de-natitingou-fast-natitingou'), 'Mathématiques Informatiques', '« Mathématiques Informatiques », c''est trois ans pour apprendre à gérer des données et des infrastructures informatiques, à FAST/Natitingou (Faculté des Sciences et Techniques de Natitingou) (au programme : Anglais, PCT et Maths). Un ancrage clair dans la tech et le digital, avec des suites comme cadres de télécommunications optiques et des nouvelles technologies de l''information et de la communication.', '3 ans (Licence)', 'Baccalauréat C ou D', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 83 places boursières et 43 places « aide/FPP » (partiellement payantes) sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme cadres de télécommunications optiques et des nouvelles technologies de l''information et de la communication, enseignants des lycées et collèges (BAPES et CAPES en Maths), accès aux écoles d''ingénieur ou accès à un master recherche ou professionnel en mathématique ou en informatique pouvant déboucher sur une thèse de doctorat.', 'Selon ton classement : 83 places boursières (gratuité + allocation de l''État) et 43 places aide/FPP (scolarité partiellement prise en charge). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Ce que tu sais faire en sortant : t''appuyer sur Anglais, PCT et Maths pour évoluer sereinement dans les systèmes d’information, un premier pas vers un poste de cadres de télécommunications optiques et des nouvelles technologies de l''information et de la communication, grâce à une bonne dose de terrain (stages, TD, projets).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Mathématiques Informatiques » : Anglais, PCT et Maths.', 83, 43, 'Classement', '["C","D"]'::jsonb, '["Anglais","PCT","Maths"]'::jsonb, '[]'::jsonb)
