INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('aquaculture', (SELECT id FROM ecoles WHERE slug = 'ecole-daquaculture-eaq'), 'Aquaculture', '« Aquaculture » (EAq (École d''Aquaculture)) s''adresse à celles et ceux qui veulent donner un métier à la terre béninoise (au programme : SVT, Maths et PCT). Un parcours de licence accessible dès le bac C, D, DEAT/Pêche, aquaculture ou DEAT/Production animale, pensé pour l’agriculture et le monde rural.', '3 ans (Licence)', 'Baccalauréat C, D, DEAT/Pêche, aquaculture ou DEAT/Production animale', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 31 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Une fois diplômé(e), tu peux viser des postes ou des activités comme chargé des entreprises aquacoles, technicien en production de poissons, crabes, huîtres et de moules, technicien en conception et fabrication des aliments pour les espèces aquacoles d''élevage, technicien en conception, fabrication et entretien semences aquacoles ou conseiller/Assistant en aquaculture.', 'Selon ton classement : 31 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Aquaculture », tu es capable d''évoluer dans l’agriculture et le monde rural grâce à de bonnes bases en SVT, Maths et PCT, un premier pas vers un poste de chargé des entreprises aquacoles, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Aquaculture » : SVT, Maths et PCT.', 31, 0, 'Classement', '["C","D","DEAT/Pêche","aquaculture","DEAT/Production animale"]'::jsonb, '["SVT","Maths","PCT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
