INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('gestion-et-production-vegetale-et-semenciere', (SELECT id FROM ecoles WHERE slug = 'ecole-de-gestion-et-de-production-vegetale-et-semenciere-egpvs'), 'Gestion et Production Végétale et Semencière', '« Gestion et Production Végétale et Semencière » accessible dès le bac C, D ou DEAT/PV, dispensée par EGPVS (École de Gestion et de Production Végétale et Semencière), forme à cultiver, produire et nourrir (au programme : SVT, Maths et PCT), avec des suites comme entrepreneur en production végétale ou technicien en production de semences.', '3 ans (Licence)', 'Baccalauréat C, D ou DEAT/PV', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 60 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers entrepreneur en production végétale, technicien en production de semences, technicien en analyse de la fertilité des sols, assistants en élaboration de plans d''entreprise de production végétale et de semences, technicien en protection des végétaux, technicien en biotechnologie végétale ou assistant de recherche agricole.', 'Selon ton classement : 60 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Gestion et Production Végétale et Semencière », tu es capable d''évoluer dans la production et la transformation agricoles grâce à de bonnes bases en SVT, Maths et PCT, un premier pas vers un poste d''entrepreneur en production végétale, mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Gestion et Production Végétale et Semencière » : SVT, Maths et PCT.', 60, 0, 'Classement', '["C","D","DEAT/PV"]'::jsonb, '["SVT","Maths","PCT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
