INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('industrie-des-bio-ressources-ibr', (SELECT id FROM ecoles WHERE slug = 'ecole-des-sciences-et-techniques-de-conservation-et-transformation-des-produits-'), 'Industrie des Bio-Ressources (IBR)', '« Industrie des Bio-Ressources (IBR) », c''est trois ans pour apprendre à donner un métier à la terre béninoise, à ESTCTPA (École des Sciences et Techniques de Conservation et Transformation des Produits Agricoles). Un ancrage clair dans l’agriculture et le monde rural, avec des suites comme technicien supérieur en industrie des industries cosmétiques et de parfumerie: savons, lotion, huiles essentielles.', '3 ans (Licence)', 'Baccalauréat toutes séries confondues', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 22 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers technicien supérieur en industrie des industries cosmétiques et de parfumerie: savons, lotion, huiles essentielles, technicien supérieur dans les industries cosmétiques et de parfumerie: savons, lotion, huiles essentielles, technicien supérieur en phytothérapie: savons, lotion, huiles essentielles, producteur de biogaz, fabricant d''huiles végétales et de corps gras, fabricant d''aliments pour bétail domestique, conseiller en gestion des procédés post-récoltes, technicien en traitements chimiques et organiques des produits agricoles en stock ou enseignant dans les lycées techniques agricoles.', 'Selon ton classement : 22 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Industrie des Bio-Ressources (IBR) », tu maîtrises les bases théoriques et pratiques qu''il faut pour la production et la transformation agricoles, un premier pas vers un poste de technicien supérieur en industrie des industries cosmétiques et de parfumerie: savons, lotion, huiles essentielles, construites au fil des stages et travaux pratiques.', 'Le contenu précis du programme (matières, volumes horaires par semestre) est à demander directement à l''établissement.', 22, 0, 'Classement', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb)
