INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('electrification-rurale-et-energies-renouvelables-erer', (SELECT id FROM ecoles WHERE slug = 'ecole-de-genie-rural-egr'), 'Electrification Rurale et Energies Renouvelables (ERER)', 'Avec « Electrification Rurale et Energies Renouvelables (ERER) », proposée par EGR (École de Génie Rural), tu apprends à moderniser les pratiques agricoles (au programme : Maths, SPCT et Français). Une licence de 3 ans tournée vers la production et la transformation agricoles, avec des suites comme industries de transformation et Unités de Production (agroalimentaire, cimenterie, production de sucre, lait, brasserie, coton, huile de palme, etc. utilisant du biogaz ou autres énergies renouvelables) ou garages automobiles.', '3 ans (Licence)', 'Baccalauréat C, D, E, F1, F2, F3, DT/Electrotech ou DT/EAp', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 17 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers industries de transformation et Unités de Production (agroalimentaire, cimenterie, production de sucre, lait, brasserie, coton, huile de palme, etc. utilisant du biogaz ou autres énergies renouvelables), garages automobiles, entreprises travaillant dans le secteur des énergies vertes, projets d''électrification rurale, fermes et entreprises agropastorales, etablissements d''enseignement technique ou entrepreneuriat sur les énergies vertes et le développement durable.', 'Selon ton classement : 17 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Electrification Rurale et Energies Renouvelables (ERER) », tu es capable d''évoluer dans l’agriculture et le monde rural grâce à de bonnes bases en Maths, SPCT, Français et F3, un premier pas vers un poste d''industries de transformation et Unités de Production (agroalimentaire, cimenterie, production de sucre, lait, brasserie, coton, huile de palme, etc. utilisant du biogaz ou autres énergies renouvelables), mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Electrification Rurale et Energies Renouvelables (ERER) » : Maths, SPCT, Français, F3, DT et Etude Electronique.', 17, 0, 'Classement', '["C","D","E","F1","F2","F3","DT/Electrotech","DT/EAp"]'::jsonb, '["Maths","SPCT","Français","pour F2","F3","DT/Electrotech: Electrotechnique appliquée","pour DT/EAp: Sciences Appliquées","Français","Etude Electronique"]'::jsonb, '[]'::jsonb)
