INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('finance-agricole-fa', (SELECT id FROM ecoles WHERE slug = 'ecole-dagrobusiness-et-de-politiques-agricoles-eapa'), 'Finance Agricole (FA)', 'EAPA (École d''Agrobusiness et de Politiques Agricoles) et sa licence « Finance Agricole (FA) » t''emmènent vers les champs, les fermes et les coopératives (au programme : Maths, SPCT et SVT). Tu y apprends à faire pousser et faire vivre la terre, avec des suites comme entrepreneur agricole ou gestionnaire d''entreprises agricoles et agro-industrielles.', '3 ans (Licence)', 'Baccalauréat C, D ou DEAT/Toutes les options', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 16 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Sur le marché du travail, cette formation ouvre notamment vers entrepreneur agricole, gestionnaire d''entreprises agricoles et agro-industrielles ou gestionnaire de coopératives et associations de producteurs.', 'Selon ton classement : 16 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Maths, SPCT et SVT, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec le monde agricole, un premier pas vers un poste d''entrepreneur agricole.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Finance Agricole (FA) » : Maths, SPCT et SVT.', 16, 0, 'Classement', '["C","D","DEAT/Toutes les options"]'::jsonb, '["Maths","SPCT","SVT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
