INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('sociologie-rurale-et-vulgarisation-agricole', (SELECT id FROM ecoles WHERE slug = 'ecole-de-sociologie-rurale-et-de-vulgarisation-agricole-esrva'), 'Sociologie rurale et Vulgarisation Agricole', '« Sociologie rurale et Vulgarisation Agricole » accessible dès le bac C, D ou DEAT/toutes options, dispensée par ESRVA (École de Sociologie rurale et de Vulgarisation Agricole), forme à donner un métier à la terre béninoise (au programme : Maths, SPCT et SVT), avec des suites comme technicien supérieur des entreprises agricoles ou technicien supérieur en Vulgarisateur/conseil agricole.', '3 ans (Licence)', 'Baccalauréat C, D ou DEAT/toutes options', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 43 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Côté débouchés, cette filière mène vers des métiers comme technicien supérieur des entreprises agricoles, technicien supérieur en Vulgarisateur/conseil agricole, technicien de recherche dans les institutions de recherche nationales et internationales dans le domaine de la sociologie rurale et de la vulgarisation agricole, conseiller technique de cabinet de conseil agricole et vulgarisation, fonctionnaire d''Etat (ministères), technicien de recherche dans les affaires techniques et financières des banques, conseiller technique en gestion des organisations paysannes et syndicats paysans, techniciens calculateurs et gestion des parcs et aires protégées (problématiques des populations riveraines), conseiller technique en nutrition humaine, enseignants des établissements et lycées et chaines de valeur agricole ou fonctionnaire des organisations de développement international (PNUD, Banque Mondiale, SNV, USAID etc).', 'Selon ton classement : 43 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'Cette licence te donne une vraie maîtrise de Maths, SPCT et SVT, avec la pratique de terrain qui va avec : travaux pratiques, stages, projets concrets en lien avec les champs, les fermes et les coopératives, un premier pas vers un poste de technicien supérieur des entreprises agricoles.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Sociologie rurale et Vulgarisation Agricole » : Maths, SPCT et SVT.', 43, 0, 'Classement', '["C","D","DEAT/toutes options"]'::jsonb, '["Maths","SPCT","SVT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
