INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('foresterie-tropicale', (SELECT id FROM ecoles WHERE slug = 'ecole-de-foresterie-tropicale-efort'), 'Foresterie Tropicale', 'Avec « Foresterie Tropicale », proposée par EForT (École de Foresterie Tropicale), tu apprends à prendre soin du bétail et de la volaille (au programme : Maths, SPCT et SVT). Une licence de 3 ans tournée vers la santé animale, avec des suites comme forestier Gestionnaire des ressources naturelles (forêts, Eaux et Chasse) ou forestier Gestionnaire des réserves de faune et des aires protégées.', '3 ans (Licence)', 'Baccalauréat C, D ou DEAT/Foresterie', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Cette année, 27 places boursières sont ouvertes sur cette filière ; au-delà, l''inscription se fait à titre payant.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers forestier Gestionnaire des ressources naturelles (forêts, Eaux et Chasse), forestier Gestionnaire des réserves de faune et des aires protégées, cartographe forestier, sylviculteur (Planteur de bois d''oeuvre, de service et mangrove et reboisement), gestionnaire des Unités de productions sylvicoles, opérateur pilote de drones (Véhicule aérien sans humain à bord) pour les relevés de données en forêt et traitement d''images, ebéniste et designer, producteur de bois de dendroénergie, spécialiste de la domestication et élevage de gibiers, spécialiste des façonnages et transformations du bois ligneux (PFNL y compris miel, viande de bois) et des produits forestiers non conventionnel et (dendrogenil), chercheur des cabinets d''étude d''impact environnemental et de laboratoirat de recherche, enseignant dans les lycées techniques agricoles ou fonctionnaire dans les Ministères (MCVDD, MAEP) et des Organisations Non Gouvernementales (ONG).', 'Selon ton classement : 27 places boursières (gratuité + allocation de l''État). Au-delà de ces quotas, l''inscription se fait à titre entièrement payant, selon le tarif fixé par l''établissement.', 'À la sortie de « Foresterie Tropicale », tu es capable d''évoluer dans les fermes et les cliniques vétérinaires grâce à de bonnes bases en Maths, SPCT et SVT, un premier pas vers un poste de forestier Gestionnaire des ressources naturelles (forêts, Eaux et Chasse), mises en pratique via des stages et des travaux dirigés.', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Foresterie Tropicale » : Maths, SPCT et SVT.', 27, 0, 'Classement', '["C","D","DEAT/Foresterie"]'::jsonb, '["Maths","SPCT","SVT","DEAT: 3 matières écrites"]'::jsonb, '[]'::jsonb)
