INSERT INTO filieres (slug, ecole_id, nom, description, duree_etudes, niveau_entree, conditions_admission, debouches, cout_annuel_info, competences_visees, programme_resume, bourse, aide_fpp, mode_entree, bac_recommande, matieres, careers)
VALUES ('micro-finance', (SELECT id FROM ecoles WHERE slug = 'ufr-financement-et-micro-financement-ufr-fmf'), 'Micro Finance', '« Micro Finance » (UFR/FMF (UFR Financement et Micro financement)) s''adresse à celles et ceux qui veulent gérer, chiffrer et faire tourner une activité (au programme : Economieou Mathsou Etude de Cas, Français et Anglais). Un parcours de licence accessible dès le bac B, C, D, G2 ou G3, pensé pour la gestion et la finance.', '3 ans (Licence)', 'Baccalauréat B, C, D, G2 ou G3', 'L''entrée se fait par le classement national du bac (ta moyenne au bac, calculée avec les coefficients de ta série, détermine ton rang). Les quotas de bourses et de places FPP sont fixés chaque année par le Ministère selon la filière.', 'Après cette formation, plusieurs portes s''ouvrent : tu peux te tourner vers inspecteurs des Finances, option Micro Finance, agent des Systèmes Financiers Décentralisés (SFD), animateur/Facilitateur Communautaire, gestionnaire des caisses communautaires, chef cabinets d''Audit financier ou entrepreneur.', 'Formation à titre payant : les tarifs et modalités sont à demander directement auprès de l''établissement.', 'Ce que tu sais faire en sortant : t''appuyer sur Economieou Mathsou Etude de Cas, Français et Anglais pour évoluer sereinement dans la finance, le commerce et la gestion de projets, un premier pas vers un poste d''inspecteurs des Finances, option Micro Finance, grâce à une bonne dose de terrain (stages, TD, projets).', 'Trois années (L1 à L3) organisées en semestres, avec cours magistraux, travaux dirigés et stages. Les matières clés de « Micro Finance » : Economieou Mathsou Etude de Cas, Français et Anglais.', 0, 0, 'Classement', '["B","C","D","G2","G3"]'::jsonb, '["Economie(B)ou Maths(C,D)ou Etude de Cas(G2,G3)","Français","Anglais"]'::jsonb, '[]'::jsonb)
